/**
 * Simulate a custom event scenario based on user input
 * 
 * @param {string} eventType - "traffic" | "industrial" | "flood" | "custom"
 * @param {string} condition - User's condition description
 */
export async function simulateScenario(eventType, condition) {
  const categoryMap = {
    traffic: "predictive",
    industrial: "rare",
    flood: "predictive",
    custom: "predictive"
  };

  const category = categoryMap[eventType] || "predictive";

  // Build prompt for simulation
  const simulationPrompt = `You are the CivicAI Decision Engine for urban risk intelligence. 

Simulate a scenario based on the following input:

EVENT TYPE: ${eventType.toUpperCase()}
CONDITION: ${condition}

Analyze this scenario and predict what may happen next. Return ONLY a valid JSON object with these exact fields:

{
  "predictedEventChain": ["Step 1: Initial event", "Step 2: Secondary effect", "Step 3: Potential outcome"],
  "cascadingImpacts": ["Impact 1", "Impact 2", "Impact 3"],
  "riskLevel": "Low" | "Moderate" | "High" | "Critical",
  "confidenceScore": 75,
  "recommendedActions": ["Action 1 — immediate", "Action 2", "Action 3"],
  "estimatedTimeToImpact": {
    "immediate": "What will happen in 0-2 hours",
    "shortTerm": "What will happen in 2-6 hours",
    "longTerm": "What will happen in 6-24 hours"
  }
}

Be predictive and specific. This is a simulation for emergency planning purposes.`;

  // Fallback for simulation
  const simulationFallback = {
    predictedEventChain: [
      `Initial: ${condition}`,
      "Secondary: cascading effects developing",
      "Potential: escalation if no intervention"
    ],
    cascadingImpacts: [
      "Infrastructure stress increasing",
      "Emergency response time may increase",
      "Public safety concerns emerging"
    ],
    riskLevel: "Moderate",
    confidenceScore: 65,
    recommendedActions: [
      "Monitor situation continuously",
      "Pre-position emergency resources",
      "Prepare public communications"
    ],
    estimatedTimeToImpact: {
      immediate: "Situation developing - monitor closely",
      shortTerm: "Potential impacts within 2-6 hours if condition persists",
      longTerm: "Full impact within 6-24 hours depending on intervention"
    }
  };

  try {
    const res = await fetch(GEMINI_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        contents: [{ parts: [{ text: simulationPrompt }] }],
        generationConfig: { temperature: 0.4, maxOutputTokens: 1200 },
      }),
    });

    if (!res.ok) {
      console.warn("Gemini API error:", res.status, await res.text());
      return simulationFallback;
    }

    const data = await res.json();
    const raw = data?.candidates?.[0]?.content?.parts?.[0]?.text ?? "";
    const clean = raw.replace(/```json\s*/gi, "").replace(/```\s*/g, "").trim();

    try {
      const parsed = JSON.parse(clean);
      return parsed;
    } catch {
      console.warn("JSON parse failed. Raw:", clean.slice(0, 300));
      return simulationFallback;
    }
  } catch (err) {
    console.warn("Network error:", err.message);
    return simulationFallback;
  }
}
